@dataclass(frozen=True)
class Planned:
    """A question and the run that answers it correctly."""

    id: str
    kind: str
    text: str
    # The attached files as run-request.v1 carries them; none for a question without files.
    files: list[dict[str, str]]
    # The tool calls a correct run makes, in order, final_answer not included.
    calls: list[tuple[str, dict[str, Any]]]
    # How many of calls each model reply holds, in order: two calls that do not need each other's
    # result come in one reply (P2.1).
    calls_per_reply: tuple[int, ...]
    answer: str
    # go_no_go's Question fields: how the scorer computes and checks the answer.
    expected: dict[str, Any]
    expected_calls: list[dict[str, Any]]
    wrong_if_matches: str | None
    # The sampling seed a held-out run is sent with (run-request.v1).
    seed: int


@dataclass(frozen=True)
class _Candidate:
    """A question before its phrasing: the calls, the answer's template values and the scorer's
    spec. texts are the phrasings it may take."""

    texts: tuple[str, ...]
    fields: dict[str, Any]
    calls: list[tuple[str, dict[str, Any]]]
    answer: str
    expected: dict[str, Any]
    expected_calls: list[dict[str, Any]]
    wrong_if_matches: str | None = None
    # As Planned's; None is one call per reply.
    calls_per_reply: tuple[int, ...] | None = None


def data_dir(spec_path: Path) -> Path:
    """<output_dir>/<first 12 hex digits of the experiment file's sha256>: a changed file never
    reads or overwrites another file's data (D11)."""
    spec = yaml.safe_load(spec_path.read_text())
    digest = hashlib.sha256(spec_path.read_bytes()).hexdigest()[:12]
    return Path(spec["output_dir"]).expanduser() / digest


def _rng(spec: dict[str, Any], split: str, stream: str) -> random.Random:
    """One random stream per split and purpose, so the number of one kind's questions does not
    change another kind's draws. A str seed is hashed with sha512, the same on every run."""
    return random.Random(f"{spec['seeds'][split]}:{stream}")


def shown(number: float) -> str:
    """A number as the answer writes it: as the tool result shows it, without a trailing .0."""
    return str(int(number)) if float(number).is_integer() else json.dumps(number)


def _numbers(value: Any) -> list[float]:
    """Every number in a tool result, at any depth."""
    if isinstance(value, bool):
        return []
    if isinstance(value, int | float):
        return [float(value)]
    if isinstance(value, dict):
        return [n for item in value.values() for n in _numbers(item)]
    if isinstance(value, list):
        return [n for item in value for n in _numbers(item)]
    return []


def _separated(expected: float, seen: Iterable[float], tolerance: float, decimals: int) -> bool:
    """True when every number the model sees, other than the answer's own (as a result rounds
    it), is more than the go/no-go's tolerance from the answer: a model that copies another
    group's value, the sum of all groups or an operand then scores wrong (P1.6d). The answer must
    be positive too: the scorer reads numbers without a sign."""
    rounding = 10**-decimals
    return expected > 0 and all(
        abs(n - expected) <= rounding or abs(n - expected) > tolerance * expected for n in seen
    )


def _amount(cents: int) -> str:
    """An amount in cents, written with 2 decimals."""
    return f"{cents // 100}.{cents % 100:02d}"


def make_file(rng: random.Random, pool: dict[str, Any], table: dict[str, Any]) -> dict[str, str]:
    """A CSV like experiments/data/sales.csv: one row per combination of the text columns'
    values, a count column, and an amount column = count x the row's price, which is set by the
    value of the priced column."""
    texts = rng.sample(sorted(pool["text_columns"]), table["text_columns"])
    priced = rng.choice(sorted(pool["priced_columns"]))
    columns = [*texts, priced]
    options = {**pool["text_columns"], **pool["priced_columns"]}
    low, high = table["values_per_column"]
    # A pool list shorter than the upper bound gives all of its values at most.
    values = {
        column: rng.sample(options[column], rng.randint(low, min(high, len(options[column]))))
        for column in columns
    }
    count_column, amount_column = rng.choice(pool["number_columns"])
    prices = {value: rng.randint(*table["price_cents"]) for value in values[priced]}
    out = io.StringIO()
    writer = csv.writer(out, lineterminator="\n")
    writer.writerow([*columns, count_column, amount_column])
    for combination in itertools.product(*(values[column] for column in columns)):
        count = rng.randint(*table["count"])
        writer.writerow([*combination, count, _amount(count * prices[combination[-1]])])
    file_id = rng.choice(pool["files"])
    return {"id": file_id, "name": f"{file_id}.csv", "content": out.getvalue()}


class _Context:
    """What every candidate of one file needs: the file, its table and rows, and the settings the
    tools and the scorer use."""

    def __init__(
        self, file: dict[str, str], tolerance: float, max_rows: int, max_chars: int, decimals: int
    ) -> None:
        self.file = file
        self.files = [file]
        # The question's fields that come from the file, not from a candidate.
        self.fields = {"file": file["name"]}
        self.table: Table = parse_file(file["id"], file["name"], file["content"])
        self.rows = list(csv.DictReader(io.StringIO(file["content"])))
        self.tolerance = tolerance
        self.max_rows = max_rows
        self.max_chars = max_chars
        self.decimals = decimals
        self.texts = [c for c in self.table.columns if self.table.types[c] == "text"]
        self.numbers = [c for c in self.table.columns if self.table.types[c] == "number"]

    def run(self, name: str, arguments: dict[str, Any]) -> dict[str, Any]:
        result = run_tool(
            name,
            arguments,
            {self.file["id"]: self.table},
            self.max_rows,
            self.max_chars,
            self.decimals,
        )
        if "error" in result:
            raise ValueError(f"{self.file['id']}: planned call {name} {arguments}: {result}")
        return result

    def total(self, value: str) -> float:
        return sum(float(row[value]) for row in self.rows)

    def valid(self, expected: dict[str, Any], results: list[dict[str, Any]]) -> bool:
        seen = [n for result in results for n in _numbers(result)]
        seen.append(self.total(expected["value"]))
        answer = expected_value(self.rows, expected)
        return _separated(answer, seen, self.tolerance, self.decimals)

    def groups(self, by: str) -> list[str]:
        return sorted({row[by] for row in self.rows})


def _row_of(result: dict[str, Any], group: str) -> float:
    agg = result["agg"]
    value: float = next(row[agg] for row in result["rows"] if row["group"] == group)
    return value


def _summary(c: _Context) -> Iterable[_Candidate]:
    for value in c.numbers:
        call = (CSV_SUMMARY, {"file": c.file["id"]})
        result = c.run(*call)
        expected = {"kind": "aggregate", "agg": "mean", "value": value}
        if not c.valid(expected, [result]):
            continue
        mean = next(col["mean"] for col in result["columns"] if col["name"] == value)
        yield _Candidate(
            texts=SUMMARY,
            fields={"value": value},
            calls=[call],
            answer=f"The average {value} per row in {c.file['name']} is {shown(mean)}.",
            expected=expected,
            expected_calls=[{"tool": CSV_SUMMARY}],
        )


def _group(c: _Context, agg: str) -> Iterable[_Candidate]:
    texts, measure = (
        (GROUP_TOTAL, "total {}") if agg == "sum" else (GROUP_MEAN, "average {} per row")
    )
    for by, value in itertools.product(c.texts, c.numbers):
        call = (GROUP_BY, {"file": c.file["id"], "by": by, "value": value, "agg": agg})
        result = c.run(*call)
        for group in c.groups(by):
            expected = {
                "kind": "aggregate",
                "agg": agg,
                "value": value,
                "group": {"by": by, "equals": group},
            }
            if not c.valid(expected, [result]):
                continue
            yield _Candidate(
                texts=texts,
                fields={"value": value, "by": by, "group": group},
                calls=[call],
                answer=f"The {measure.format(value)} of the {by} {group} is "
                f"{shown(_row_of(result, group))}.",
                expected=expected,
                expected_calls=[{"tool": GROUP_BY}],
            )


def _wrong_direction(higher: str, lower: str) -> str:
    """An answer that says the higher group is lower, or the lower one higher, built like
    demo-go-no-go.yaml's compare regex: the comparative has its "than" within two words, up to
    the end of the sentence (a "." followed by a digit is a decimal point, not an end)."""
    high, low = re.escape(higher.lower()), re.escape(lower.lower())
    return (
        rf"\b{high}\b(?:[^.]|\.\d)*\b(?:less|lower|fewer|smaller)(?:\s+\w+){{0,2}}\s+than\b"
        rf"|\b{low}\b(?:[^.]|\.\d)*\b(?:more|higher|greater|larger)(?:\s+\w+){{0,2}}\s+than\b"
    )


def _compare(c: _Context) -> Iterable[_Candidate]:
    for by, value in itertools.product(c.texts, c.numbers):
        for first, second in itertools.combinations(c.groups(by), 2):
            arguments = {"file": c.file["id"], "by": by, "value": value, "agg": "sum"}
            result = c.run(COMPARE, {**arguments, "left": first, "right": second})
            if result["difference"] == 0:
                continue
            higher, lower = result["higher"]["group"], result["lower"]["group"]
            # As the demo asks it: left is the lower group, right the higher one.
            call = (COMPARE, {**arguments, "left": lower, "right": higher})
            result = c.run(*call)
            expected = {
                "kind": "difference",
                "agg": "sum",
                "value": value,
                "by": by,
                "left": lower,
                "right": higher,
            }
            if not c.valid(expected, [result]):
                continue
            yield _Candidate(
                texts=COMPARE_TEXTS,
                fields={"value": value, "by": by, "higher": higher, "lower": lower},
                calls=[call],
                answer=f"The {by} {higher} had {shown(result['difference'])} more total {value} "
                f"than the {by} {lower}.",
                expected=expected,
                expected_calls=[{"tool": COMPARE}],
                wrong_if_matches=_wrong_direction(higher, lower),
            )


def _two_step(c: _Context) -> Iterable[_Candidate]:
    for by, (rank_value, value) in itertools.product(c.texts, itertools.permutations(c.numbers)):
        for rank_agg, agg in itertools.product(RANK, ASKED):
            rank_args = {"file": c.file["id"], "by": by, "value": rank_value, "agg": rank_agg}
            ranked = c.run(GROUP_BY, rank_args)
            first, runner_up = ranked["rows"][0], ranked["rows"][1]
            top = first["group"]
            asked_call = (GROUP_BY, {"file": c.file["id"], "by": by, "value": value, "agg": agg})
            asked = c.run(*asked_call)
            # A tie for first place has two answers; the same top group in both lets one call
            # answer by luck.
            if first[rank_agg] == runner_up[rank_agg] or asked["rows"][0]["group"] == top:
                continue
            expected = {
                "kind": "of_top_group",
                "by": by,
                "rank": {"agg": rank_agg, "value": rank_value},
                "agg": agg,
                "value": value,
            }
            if not c.valid(expected, [ranked, asked]):
                continue
            rank, asked_text = RANK[rank_agg].format(rank_value), ASKED[agg].format(value)
            yield _Candidate(
                texts=TWO_STEP,
                fields={"by": by, "rank": rank, "asked": asked_text},
                calls=[(GROUP_BY, rank_args), asked_call],
                answer=f"The {by} {top} has {rank} ({shown(first[rank_agg])}); its {asked_text} "
                f"is {shown(_row_of(asked, top))}.",
                expected=expected,
                expected_calls=[
                    {
                        "tool": GROUP_BY,
                        "arguments": {"by": by, "value": rank_value, "agg": rank_agg},
                    }
                ],
            )


CSV_KINDS: dict[str, Callable[[_Context], Iterable[_Candidate]]] = {
    "summary": _summary,
    "group-total": lambda c: _group(c, "sum"),
    "group-mean": lambda c: _group(c, "mean"),
    "compare": _compare,
    "two-step": _two_step,
}


def _contains(answer: str, texts: list[str]) -> dict[str, Any]:
    """The scorer's spec of a text answer (go_no_go.CONTAINS). Raises ValueError when the answer
    lacks one of the texts, so a pool value that a tool's result does not carry whole stops the
    generator instead of making a question no run can pass."""
    missing = [text for text in texts if text.casefold() not in answer.casefold()]
    if missing:
        raise ValueError(f"the answer {answer!r} lacks {missing}")
    return {"kind": CONTAINS, "texts": texts}


def _one_section_each(sections: Sequence[tuple[str, str]], phrases: Sequence[str]) -> bool:
    """True when each section's phrase is in that section's text and in no other's, so an answer
    that quotes the wrong section lacks it."""
    return all(
        phrase in sections[i][1] and sum(phrase in text for _, text in sections) == 1
        for i, phrase in enumerate(phrases)
    )


def _document(file_id: str, title: str, sections: Sequence[tuple[str, str]]) -> dict[str, str]:
    """A text document as run-request.v1 carries it: a title line (in no section, so no tool reads
    it), then one "## <heading>" section per (heading, text)."""
    body = "".join(f"\n## {heading}\n{text}\n" for heading, text in sections)
    return {"id": file_id, "name": f"{file_id}.txt", "type": "text", "content": title + "\n" + body}


@dataclass(frozen=True)
class _Rule:
    """A policy's day rule: the phrase that names it in the text, its days, and whether they are
    calendar days counted from the delivery, the only rule draft_reply gives a deadline for."""

    phrase: str
    days: int
    calendar: bool


class _FileSet:
    """One run's attached files, read as the runtime reads them, and the settings the tools use."""

    def __init__(self, files: list[dict[str, str]], config: AgentConfig) -> None:
        self.files = files
        self.config = config
        tables, documents = read_run_files(files, config.max_files, config.max_file_bytes)
        self.tables = {table.id: table for table in tables}
        self.documents = {document.id: document for document in documents}
        # Every field of these questions comes from a candidate.
        self.fields: dict[str, str] = {}

    def run(self, name: str, arguments: dict[str, Any]) -> dict[str, Any]:
        result = run_call(name, arguments, self.tables, self.documents, self.config)
        if "error" in result:
            raise ValueError(f"{self.files[0]['id']}: planned call {name} {arguments}: {result}")
        return result


class _Support(_FileSet):
    """An orders CSV and a policies document (P2.1a-2), with the rule of each policy."""

    def __init__(
        self,
        orders: dict[str, str],
        policies: dict[str, str],
        rules: dict[str, _Rule],
        config: AgentConfig,
    ) -> None:
        super().__init__([orders, policies], config)
        self.orders = self.tables[orders["id"]]
        self.policies = self.documents[policies["id"]]
        # Keyed by the topic enum's value.
        self.rules = rules
        self.rows = list(csv.DictReader(io.StringIO(orders["content"])))


class _Contracts(_FileSet):
    """Two versions of a contract (P2.1a-1), with each version's value of each clause."""

    def __init__(
        self,
        files: list[dict[str, str]],
        values: dict[str, dict[str, str]],
        changed: list[str],
        config: AgentConfig,
    ) -> None:
        super().__init__(files, config)
        self.left, self.right = (self.documents[file["id"]] for file in files)
        # Document ID -> clause enum value -> the value the clause's text holds.
        self.values = values
        # The clauses whose value differs between the versions.
        self.changed = changed


def make_orders(rng: random.Random, spec: dict[str, Any], pool: dict[str, Any]) -> dict[str, str]:
    """An orders CSV like agent/tests/fixtures/orders.csv. A shipped order has no delivered_on."""
    shape = spec["orders"]
    first, last = (date.fromisoformat(day) for day in shape["ordered_on"])
    low, high = shape["order_id"]
    ids = sorted(rng.sample(range(low, high + 1), rng.randint(*shape["count"])))
    out = io.StringIO()
    writer = csv.writer(out, lineterminator="\n")
    writer.writerow(ORDER_COLUMNS)
    for order_id in ids:
        ordered = first + timedelta(days=rng.randint(0, (last - first).days))
        shipped = rng.random() < shape["shipped_share"]
        delivered = ordered + timedelta(days=rng.randint(*shape["delivery_days"]))
        writer.writerow(
            [
                order_id,
                rng.choice(pool["customers"]),
                rng.choice(pool["items"]),
                SHIPPED if shipped else DELIVERED,
                ordered.isoformat(),
                "" if shipped else delivered.isoformat(),
                _amount(rng.randint(*shape["amount_cents"])),
            ]
        )
    file_id = rng.choice(pool["orders_files"])
    return {"id": file_id, "name": f"{file_id}.csv", "type": "csv", "content": out.getvalue()}


def make_policies(
    rng: random.Random, spec: dict[str, Any], pool: dict[str, Any]
) -> tuple[dict[str, str], dict[str, _Rule]]:
    """A policies document like agent/tests/fixtures/policies.txt and each policy's rule. The days
    are drawn again until each rule's phrase is in its own policy alone ("4 days" is in "14
    days")."""
    templates: dict[str, str] = pool["policies"]
    titles = rng.sample(list(templates), rng.randint(*spec["policies"]["count"]))
    low, high = spec["policies"]["rule_days"]
    while True:
        days = rng.sample(range(low, high + 1), len(titles))
        sections = [
            (title, templates[title].format(days=d)) for title, d in zip(titles, days, strict=True)
        ]
        rules = []
        for title, d in zip(titles, days, strict=True):
            working = WORKING_DAYS in templates[title]
            phrase = WORKING_DAYS.format(days=d) if working else f"{d} days"
            rules.append(_Rule(phrase, d, calendar=not working))
        if _one_section_each(sections, [rule.phrase for rule in rules]):
            break
    file_id = rng.choice(pool["policies_files"])
    document = _document(file_id, "Customer policies", sections)
    return document, {
        normalise_title(title): rule for title, rule in zip(titles, rules, strict=True)
    }


def make_support(
    rng: random.Random, spec: dict[str, Any], pool: dict[str, Any], config: AgentConfig
) -> _Support:
    orders = make_orders(rng, spec, pool)
    policies, rules = make_policies(rng, spec, pool)
    return _Support(orders, policies, rules, config)


def make_contracts(
    rng: random.Random, spec: dict[str, Any], pool: dict[str, Any], config: AgentConfig
) -> _Contracts:
    """Two versions of a contract like agent/tests/fixtures/contract-2025.txt and -2026.txt: the
    same numbered clauses, a year apart, with the value of some clauses changed. Values are drawn
    again until each version's value of a clause is in that clause alone, and a changed clause's
    new value is not in its old text, so an answer that quotes the old one lacks it."""
    clauses: dict[str, dict[str, Any]] = pool["clauses"]
    titles = rng.sample(list(clauses), rng.randint(*spec["contracts"]["count"]))
    prefix = rng.choice(pool["files"])
    year = rng.randint(*pool["years"])
    ids = [f"{prefix}-{year}", f"{prefix}-{year + 1}"]
    while True:
        before = {title: rng.choice(clauses[title]["values"]) for title in titles}
        changed = rng.sample(titles, rng.randint(*spec["contracts"]["changed"]))
        after = {
            title: rng.choice([v for v in clauses[title]["values"] if v != before[title]])
            if title in changed
            else before[title]
            for title in titles
        }
        versions = [
            [(f"{i}. {t}", clauses[t]["text"].format(values[t])) for i, t in enumerate(titles, 1)]
            for values in (before, after)
        ]
        if all(
            _one_section_each(sections, [values[t] for t in titles])
            for sections, values in zip(versions, (before, after), strict=True)
        ) and all(after[t] not in clauses[t]["text"].format(before[t]) for t in changed):
            break
    files = [
        _document(file_id, file_id, sections)
        for file_id, sections in zip(ids, versions, strict=True)
    ]
    values = {
        file_id: {normalise_title(t): chosen[t] for t in titles}
        for file_id, chosen in zip(ids, (before, after), strict=True)
    }
    return _Contracts(files, values, [normalise_title(t) for t in changed], config)


def _reply(s: _Support) -> Iterable[_Candidate]:
    """As the prompt says: get_order and get_policy (one reply, they do not need each other), then
    draft_reply, whose reply is the answer (P2.1a-2)."""
    for row, section in itertools.product(s.rows, s.policies.sections):
        order_id, topic = row[ORDER_ID], section.clause
        lookup = [
            (GET_ORDER, {"file": s.orders.id, ORDER_ID: order_id}),
            (GET_POLICY, {"file": s.policies.id, "topic": topic}),
        ]
        for call in lookup:
            s.run(*call)
        draft = (
            DRAFT_REPLY,
            {"orders": s.orders.id, ORDER_ID: order_id, "policies": s.policies.id, "topic": topic},
        )
        reply: str = s.run(*draft)["summary"]
        rule = s.rules[topic]
        texts = [order_id, section.title]
        if row["status"] == DELIVERED and rule.calendar:
            end = date.fromisoformat(row["delivered_on"]) + timedelta(days=rule.days)
            texts.append(end.isoformat())
        yield _Candidate(
            texts=REPLY_TEXTS,
            fields={"order": order_id, "topic": topic},
            calls=[*lookup, draft],
            calls_per_reply=(2, 1),
            answer=reply,
            expected=_contains(reply, texts),
            expected_calls=[
                {"tool": DRAFT_REPLY, "arguments": {ORDER_ID: order_id, "topic": topic}}
            ],
        )


def _order_status(s: _Support) -> Iterable[_Candidate]:
    for row in s.rows:
        order_id = row[ORDER_ID]
        call = (GET_ORDER, {"file": s.orders.id, ORDER_ID: order_id})
        s.run(*call)
        answer = f"Order {order_id} ({row['item']}) is {row['status']}."
        if row["status"] == DELIVERED:
            answer += f" It was delivered on {row['delivered_on']}."
        yield _Candidate(
            texts=ORDER_STATUS_TEXTS,
            fields={"order": order_id},
            calls=[call],
            answer=answer,
            expected=_contains(answer, [row["status"]]),
            expected_calls=[{"tool": GET_ORDER, "arguments": {ORDER_ID: order_id}}],
        )


def _policy(s: _Support) -> Iterable[_Candidate]:
    for section in s.policies.sections:
        call = (GET_POLICY, {"file": s.policies.id, "topic": section.clause})
        answer = f'Our {section.title} policy says: "{s.run(*call)["text"]}"'
        yield _Candidate(
            texts=POLICY_TEXTS,
            fields={"topic": section.clause},
            calls=[call],
            answer=answer,
            expected=_contains(answer, [s.rules[section.clause].phrase]),
            expected_calls=[{"tool": GET_POLICY, "arguments": {"topic": section.clause}}],
        )


def _clause_diff(c: _Contracts) -> Iterable[_Candidate]:
    """read_document on both versions (one reply), then diff_clauses, whose summary is the answer
    (P2.1a-1)."""
    for clause in c.changed:
        reads = [(READ_DOCUMENT, {"file": c.left.id}), (READ_DOCUMENT, {"file": c.right.id})]
        for call in reads:
            c.run(*call)
        arguments = {"left": c.left.id, "right": c.right.id, "clause": clause}
        summary: str = c.run(DIFF_CLAUSES, arguments)["summary"]
        yield _Candidate(
            texts=CLAUSE_DIFF_TEXTS,
            fields={"clause": clause, "left": c.left.name, "right": c.right.name},
            calls=[*reads, (DIFF_CLAUSES, arguments)],
            calls_per_reply=(2, 1),
            answer=summary,
            expected=_contains(summary, [c.values[c.right.id][clause]]),
            expected_calls=[{"tool": DIFF_CLAUSES, "arguments": arguments}],
        )


def _clause_text(c: _Contracts) -> Iterable[_Candidate]:
    for document in (c.left, c.right):
        for section in document.sections:
            arguments = {"file": document.id, "clause": section.clause}
            text = c.run(EXTRACT_CLAUSES, arguments)["text"]
            answer = f'The {section.clause} clause of {document.name} says: "{text}"'
            yield _Candidate(
                texts=CLAUSE_TEXT_TEXTS,
                fields={"clause": section.clause, "file": document.name},
                calls=[(EXTRACT_CLAUSES, arguments)],
                answer=answer,
                expected=_contains(answer, [c.values[document.id][section.clause]]),
                expected_calls=[{"tool": EXTRACT_CLAUSES, "arguments": arguments}],
            )


SUPPORT_KINDS: dict[str, Callable[[_Support], Iterable[_Candidate]]] = {
    "reply": _reply,
    "order-status": _order_status,
    "policy": _policy,
}
CONTRACT_KINDS: dict[str, Callable[[_Contracts], Iterable[_Candidate]]] = {
    "clause-diff": _clause_diff,
    "clause-text": _clause_text,
}


def _options[Scenario: (_Context, _Support, _Contracts)](
    scenarios: Sequence[Scenario], candidates: Callable[[Scenario], Iterable[_Candidate]]
) -> list[tuple[list[dict[str, str]], _Candidate, str]]:
    """Every (files, candidate, question text) of one kind across a scenario's file sets: one CSV,
    a support set or a contract pair each."""
    return [
        (scenario.files, candidate, text.format(**scenario.fields, **candidate.fields))
        for scenario in scenarios
        for candidate in candidates(scenario)
        for text in candidate.texts
    ]


def _chain(rng: random.Random, spec: dict[str, Any]) -> tuple[float, list[list[Any]]]:
    """A start number and its operations: multiplications and divisions first, then additions
    and subtractions, so reading left to right gives what the usual precedence gives. A division
    only by a number that divides exactly, a subtraction only of a smaller number, so every
    result is a positive whole number."""
    low, high = spec["arithmetic"]["operand"]
    operations = rng.randint(*spec["arithmetic"]["operations"])
    products = rng.randint(0, operations)
    value: float = rng.randint(low, high)
    start, steps = value, []
    for i in range(operations):
        if i < products:
            divisors = [n for n in range(max(low, 2), high + 1) if value % n == 0 and n < value]
            op = rng.choice(["multiply", "divide"]) if divisors else "multiply"
            number = rng.choice(divisors) if op == "divide" else rng.randint(low, high)
        else:
            smaller = [n for n in range(low, high + 1) if n < value]
            op = rng.choice(["add", "subtract"]) if smaller else "add"
            number = rng.choice(smaller) if op == "subtract" else rng.randint(low, high)
        steps.append([op, number])
        value = OPERATIONS[op](value, number)
    return start, steps


def _expression(rng: random.Random, start: float, steps: list[list[Any]]) -> str:
    text = shown(start)
    for op, number in steps:
        word = rng.choice(OPERATION_WORDS[op])
        text += f"x{shown(number)}" if word == "x" else f" {word} {shown(number)}"
    return text


def _calculator_expression(start: float, steps: list[list[Any]]) -> str:
    """The question's arithmetic as the one expression the calculator takes (P2.1a-3). _chain puts
    the multiplications and divisions first, so the usual precedence gives the chain's value."""
    return shown(start) + "".join(f"{SIGNS[op]}{shown(number)}" for op, number in steps)


def _calculated(arguments: dict[str, Any]) -> float:
    """The calculator's result for a planned call, as the agent's run_tool computes it."""
    result = run_tool(CALCULATOR, arguments, {}, 0, 0, 0)["result"]
    if not isinstance(result, int | float):
        raise ValueError(f"planned calculator call {arguments}: {result}")
    return result


def _arithmetic(
    spec: dict[str, Any], split: str, count: int, tolerance: float, decimals: int
) -> list[_Candidate]:
    """count different arithmetic questions; held-out ones are never a training question's text.
    A question whose answer is too close to one of its numbers is drawn again."""
    rng = _rng(spec, split, "arithmetic")
    train_count = spec["questions"]["train"]
    taken = (
        set()
        if split == "train"
        else {c.texts[0] for c in _arithmetic(spec, "train", train_count, tolerance, decimals)}
    )
    found: list[_Candidate] = []
    while len(found) < count:
        start, steps = _chain(rng, spec)
        expression = _expression(rng, start, steps)
        text = rng.choice(ARITHMETIC).format(expr=expression)
        calls: list[tuple[str, dict[str, Any]]] = [
            (CALCULATOR, {"expression": _calculator_expression(start, steps)})
        ]
        value = _calculated(calls[0][1])
        # One call: the model sees the question's numbers and the answer, no intermediate result.
        seen = [start, *(number for _, number in steps)]
        expected = {"kind": "arithmetic", "start": start, "steps": steps}
        if text in taken or not _separated(value, seen, tolerance, decimals):
            continue
        taken.add(text)
        found.append(
            _Candidate(
                texts=(text,),
                fields={},
                calls=calls,
                answer=f"{expression} is {shown(value)}.",
                expected=expected,
                expected_calls=[{"tool": CALCULATOR}],
            )
        )
    return found


def _off_topic(spec: dict[str, Any], split: str, count: int) -> list[_Candidate]:
    """count off-topic questions from the split's fillers; a split with fewer texts than count
    repeats them, each time with a file drawn separately."""
    rng = _rng(spec, split, "off-topic")
    pool = spec["pools"][split]["off_topic"]
    texts = [
        template.format(filler)
        for name, templates in OFF_TOPIC.items()
        for template in templates
        for filler in pool[name]
    ]
    rng.shuffle(texts)
    return [
        _Candidate(
            texts=(texts[i % len(texts)],),
            fields={},
            calls=[],
            answer=spec["off_topic_reply"],
            expected={"kind": "fixed_reply", "reply": spec["off_topic_reply"]},
            expected_calls=[],
        )
        for i in range(count)
    ]


def plan(spec: dict[str, Any], split: str, tolerance: float, config: AgentConfig) -> list[Planned]:
    """Every question of a split, kind by kind in KINDS order, questions[split] of each. Each
    scenario's files come from their own random stream, so the CSVs are the same as before P2.1b."""
    count = spec["questions"][split]
    pool = spec["pools"][split]
    files_rng = _rng(spec, split, "files")
    files = [make_file(files_rng, pool, spec["table"]) for _ in range(spec["csvs"][split])]
    max_rows, max_chars = config.max_result_rows, config.max_result_chars
    decimals = config.result_decimals
    contexts = [_Context(file, tolerance, max_rows, max_chars, decimals) for file in files]
    support_rng = _rng(spec, split, "support-files")
    supports = [
        make_support(support_rng, spec, pool["support"], config)
        for _ in range(spec["support_sets"][split])
    ]
    contracts_rng = _rng(spec, split, "contract-files")
    contracts = [
        make_contracts(contracts_rng, spec, pool["contracts"], config)
        for _ in range(spec["contract_pairs"][split])
    ]
    # The files an off-topic question may come with, per scenario.
    scenarios = [
        [c.files for c in contexts],
        [s.files for s in supports],
        [c.files for c in contracts],
    ]
    planned: list[Planned] = []
    for kind in KINDS:
        rng = _rng(spec, split, kind)
        chosen: list[tuple[list[dict[str, str]], _Candidate, str]]
        options: list[tuple[list[dict[str, str]], _Candidate, str]] | None = None
        if kind in CSV_KINDS:
            options = _options(contexts, CSV_KINDS[kind])
        elif kind in SUPPORT_KINDS:
            options = _options(supports, SUPPORT_KINDS[kind])
        elif kind in CONTRACT_KINDS:
            options = _options(contracts, CONTRACT_KINDS[kind])
        if options is not None:
            if len(options) < count:
                raise ValueError(f"{split} {kind}: {len(options)} questions, {count} asked")
            chosen = rng.sample(options, count)
        else:
            made = (
                _arithmetic(spec, split, count, tolerance, decimals)
                if kind == "arithmetic"
                else _off_topic(spec, split, count)
            )
            chosen = [
                (
                    # The calculator is offered only on runs without files (P2.1a-3). A scenario
                    # first, so each is as likely whatever its number of file sets.
                    rng.choice(rng.choice(scenarios))
                    if kind == "off-topic" and rng.random() < spec["with_file_share"]
                    else [],
                    c,
                    c.texts[0],
                )
                for c in made
            ]
        for question_files, candidate, text in chosen:
            planned.append(
                Planned(
                    id=f"{split}-{kind}-{len(planned) + 1:04d}",
                    kind=kind,
                    text=text,
                    files=question_files,
                    calls=candidate.calls,
                    calls_per_reply=candidate.calls_per_reply or (1,) * len(candidate.calls),
                    answer=candidate.answer,
                    expected=candidate.expected,
                    expected_calls=candidate.expected_calls,
                    wrong_if_matches=candidate.wrong_if_matches,
                    seed=len(planned) + 1,
                )
            )
    return planned


class ScriptedLLM(LLMClient):
    """Stands in for the LLM: returns the planned replies in order and keeps what the runtime sent
    with each call. It never calls a model, so it has no HTTP client and skips LLMClient's
    __init__."""

    def __init__(self, replies: Sequence[dict[str, Any]]) -> None:
        self._replies = iter(replies)
        self.sent: list[tuple[list[dict[str, Any]], list[dict[str, Any]]]] = []

    async def chat(
        self,
        messages: list[dict[str, Any]],
        tools: list[dict[str, Any]],
        headers: dict[str, str],
        seed: int | None,
    ) -> ChatReply:
        self.sent.append((copy.deepcopy(messages), tools))
        reply = next(self._replies)
        return ChatReply(reply, "tool_calls" if "tool_calls" in reply else "stop")


def _call_message(calls: Sequence[tuple[int, str, dict[str, Any]]]) -> dict[str, Any]:
    """An assistant message with the (number, name, arguments) tool calls, as vLLM returns it and
    the loop keeps it: the arguments a JSON string, keys in the schema's order (the plans build
    them in that order)."""
    return {
        "role": "assistant",
        "content": None,
        "tool_calls": [
            {
                "id": f"call-{index}",
                "type": "function",
                "function": {"name": name, "arguments": json.dumps(arguments)},
            }
            for index, name, arguments in calls
        ],
    }


def replies(planned: Planned, mode: str) -> list[dict[str, Any]]:
    """The model's replies in a correct run: the planned calls, calls_per_reply of them per reply,
    then final_answer (required) or the answer as text (auto, D10)."""
    if sum(planned.calls_per_reply) != len(planned.calls):
        raise ValueError(
            f"{planned.id}: calls_per_reply {planned.calls_per_reply} does not add up to its "
            f"{len(planned.calls)} calls"
        )
    numbered = iter([(i, name, args) for i, (name, args) in enumerate(planned.calls, 1)])
    calls = [_call_message([next(numbered) for _ in range(n)]) for n in planned.calls_per_reply]
    if mode == "required":
        final = (len(planned.calls) + 1, FINAL_ANSWER, {"answer": planned.answer})
        last = _call_message([final])
    else:
        last = {"role": "assistant", "content": planned.answer}
    return [*calls, last]


async def record(planned: Planned, config: AgentConfig) -> tuple[list[dict[str, Any]], RunResult]:
    """Runs the planned question through run_task in config.tool_choice's mode; one training
    example per model call."""
    mode = config.tool_choice
    script = replies(planned, mode)
    llm = ScriptedLLM(script)
    tables, documents = read_run_files(planned.files, config.max_files, config.max_file_bytes)
    run_id = f"gen-{planned.id}-{mode}"
    result = await run_task(
        planned.text, run_id, planned.seed, config, llm, tables=tables, documents=documents
    )
    examples = [
        {
            "id": f"{planned.id}-{mode}-{turn}",
            "question": planned.id,
            "kind": planned.kind,
            "mode": mode,
            "tools": tools,
            "messages": messages,
            "reply": reply,
        }
        for turn, ((messages, tools), reply) in enumerate(zip(llm.sent, script, strict=True), 1)
    ]
    return examples, result


async def _record_all(
    planned: Sequence[Planned], config: AgentConfig, modes: Sequence[ToolChoice]
) -> list[dict[str, Any]]:
    examples: list[dict[str, Any]] = []
    for question in planned:
        for mode in modes:
            recorded, result = await record(question, replace(config, tool_choice=mode))
            if result.status != "done" or result.answer != question.answer or result.invalid_calls:
                raise RuntimeError(f"{question.id} in {mode} did not run as planned: {result}")
            examples += recorded
    return examples


def generate(
    spec: dict[str, Any], config: AgentConfig, tolerance: float
) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    """The training examples of both modes and the held-out lines. Held-out questions run through
    the loop too, so a plan the runtime would reject never reaches the scorer."""
    for mode in spec["modes"]:
        if mode not in get_args(ToolChoice):
            raise ValueError(f"modes: {mode!r} is not a D10 mode {get_args(ToolChoice)}")
    train = plan(spec, "train", tolerance, config)
    heldout = plan(spec, "heldout", tolerance, config)
    examples = asyncio.run(_record_all(train, config, spec["modes"]))
    asyncio.run(_record_all(heldout, config, spec["modes"]))
    lines = [
        {
            "id": q.id,
            "kind": q.kind,
            "text": q.text,
            "seed": q.seed,
            "files": q.files,
            "expected_calls": q.expected_calls,
            "expected": q.expected,
            "wrong_if_matches": q.wrong_if_matches,
        }
        for q in heldout
    ]
    return examples, lines


def _jsonl(items: Iterable[dict[str, Any]]) -> bytes:
    return "".join(json.dumps(item) + "\n" for item in items).encode()


def main() -> None:
    parser = argparse.ArgumentParser(description="P1.7: generate training data and held-out set")
    parser.add_argument("experiment", type=Path, help="e.g. experiments/finetune-data.yaml")
    spec_path = parser.parse_args().experiment
    spec = yaml.safe_load(spec_path.read_text())
    profile_path = REPO_ROOT / "config" / f"{spec['profile']}.yaml"
    tolerance: float = yaml.safe_load(profile_path.read_text())["agent"]["answer_tolerance"]
    examples, heldout = generate(spec, load_config(profile_path), tolerance)

    out = data_dir(spec_path)
    out.mkdir(parents=True, exist_ok=True)
    train_bytes, heldout_bytes = _jsonl(examples), _jsonl(heldout)
    (out / "train.jsonl").write_bytes(train_bytes)
    (out / "heldout.jsonl").write_bytes(heldout_bytes)

    trajectories = Counter((e["kind"], e["mode"]) for e in examples if e["id"].endswith("-1"))
    turns = Counter((e["kind"], e["mode"]) for e in examples)
    for kind, mode in sorted(turns, key=lambda key: (KINDS.index(key[0]), key[1])):
        print(
            f"finetune-data: train {kind} {mode}: {trajectories[kind, mode]} trajectories, "
            f"{turns[kind, mode]} examples"
        )
    for kind, n in Counter(line["kind"] for line in heldout).items():
        print(f"finetune-data: heldout {kind}: {n} questions")
    digest = hashlib.sha256(train_bytes + heldout_bytes).hexdigest()
    print(f"finetune-data: {len(examples)} examples, {len(heldout)} held-out questions in {out}")
    print(f"finetune-data: sha256 of train.jsonl + heldout.jsonl {digest}")


if __name__ == "__main__":
    main()
